import { useState } from 'react';
import { Card, OutputList, Page } from '@hub/sdk/frontend';
import { useModules } from '../modules/ModulesContext';

/** Every file generated by the tools, checked against the disk at each visit. */
export function OutputsPage() {
  const { modules } = useModules();
  const [version, setVersion] = useState(0);
  const names = Object.fromEntries(modules.map((m) => [m.id, m.manifest.name]));
  return (
    <Page
      title="Fichiers générés"
      subtitle="Tout ce que les outils ont créé. Un fichier supprimé ou déplacé dans l’Explorateur apparaît « introuvable »."
    >
      <Card>
        <OutputList
          version={version}
          moduleNames={names}
          onChange={() => setVersion((v) => v + 1)}
          emptyText="Aucun fichier généré pour l’instant."
        />
      </Card>
    </Page>
  );
}
